def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    # Fixed early probes to avoid being exploited by always-C exploiters.
    if n == 3:
        return 'D'
    if n == 9:
        return 'D'
    # Endgame: defect on the last round.
    if n >= 99:
        return 'D'
    # Count opponent defections.
    opp_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
    opp_rate = opp_d / n
    last_opp = history[-1][1]
    if last_opp == 'D':
        if opp_rate > 0.5:
            return 'D'
        else:
            return 'C'
    else:
        return 'C'
